  ai_disclosure_title: 'Sebelum anda guna AI RuMampu',
  ai_disclosure_body: 'RuMampu menggunakan model AI yang dihoskan oleh Groq. Bergantung pada ciri, Groq menerima gambar resit, kata-kata yang anda taip atau sebut, angka berkaitan daripada rekod RuMampu anda, dan label skrin yang diperlukan untuk menjawab.',
  ai_disclosure_optional: 'AI adalah pilihan. Tiada cadangan AI ditambah pada rekod anda sehingga anda mengesahkannya.',
  ai_disclosure_continue: 'Teruskan dengan AI',
  statement_disclosure_title: 'Sebelum mengimbas penyata pendapatan',
  statement_disclosure_data: 'RuMampu menghantar imej yang anda pilih (seperti imej penyata bank atau e-penyata, atau tangkapan skrin pendapatan) kepada model penglihatan yang dihoskan oleh Groq. Imbasan hanya boleh memulangkan tarikh, amaun pendapatan yang mungkin dan tanda keyakinan. Ia tidak mengimport atau memaparkan penilaian kemampuan, kredibiliti atau kelayakan.',
  statement_disclosure_location: 'Groq menyatakan data pelanggan yang disimpan berada dalam bucket Google Cloud Platform di Amerika Syarikat. Adendum Pemprosesan Data membenarkan pemprosesan di Amerika Syarikat dan negara lain tempat Groq atau subpemprosesnya beroperasi; pemprosesan tidak dijamin hanya di Amerika Syarikat.',
  statement_disclosure_retention: 'Groq menyatakan input dan output inferens tidak disimpan secara lalai. Zero Data Retention untuk akaun Groq RuMampu kini dimatikan, jadi input dan output boleh disimpan sehingga 30 hari untuk penyelesaian masalah kebolehpercayaan atau pemantauan penyalahgunaan, atau lebih lama jika diwajibkan undang-undang. Metadata penggunaan juga dikumpulkan dan tidak mengandungi imej atau output model.',
  statement_disclosure_saved: 'RuMampu tidak menambah imej imbasan ke rekod kewangan anda. Catatan pendapatan yang dicadangkan hanya disimpan selepas anda memilih dan mengesahkannya.',
