  fh_dist: 'Mengikut daerah',
  fh_dist_h: 'Pendapatan isi rumah median ialah bagi 2024. Rumah dijual dan harga purata ialah bagi Januari hingga Mac 2026, angka awal. Purata bukan median, jadi tiada gandaan atau jalur dikira mengikut daerah.',
  fh_dist_h2: 'Homes sold and the middle price are for July 2025 to June 2026. Household income is published by state only, so every district here is measured against the state figure.',
  fh_earn: 'Keluarga biasa di {s} berpendapatan RM {m} sebulan.',
