  uf_first_src: 'Sumber: Perintah Duti Setem (Pengecualian) 2021, P.U. (A) 53/2021, dan Perintah Duti Setem (Pengecualian) (No. 2) 2021, P.U. (A) 54/2021, masing-masing seperti dipinda oleh P.U. (A) 448/2025 dan 449/2025, seperti dinyatakan dalam Pekeliling Majlis Peguam 128/2026 bertarikh 16 April 2026. Disemak 12 September 2026.',
